import {mountDashboard,icon} from './dashboard.mjs';
import {escapeHTML as esc} from './transfer-ui.mjs';
import {ACTIVATION_CODE,PAPER_PAIRS,INTERVALS,validateBotSettings,freshPaperBot,restorePaperBot,generatePaperTrade} from './paper-bot.mjs';
const dollars=c=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(c/100);
export function botsHTML(){return '<div class="bots-page paper-bots"><div class="paper-heading"><div><h1>Trading Bots</h1><p>Configure and run your paper trading strategies</p></div><span class="paper-label">SIMULATED · PAPER TRADING</span></div><div class="paper-notice"><strong>Practice account only</strong><p>Trades, prices and profits are generated. They are not real orders or investment returns. Paper funds cannot be deposited, withdrawn or transferred to your funded wallet.</p></div><section class="bots-panel bot-passkey" id="bot-activation"><h2>'+icon('shield')+' Activate Your Bot</h2><p>Enter your activation code to unlock Pro Trading Bot v2.1.</p><form id="bot-passkey-form"><label for="bot-passkey">Bot activation code</label><input id="bot-passkey" placeholder="Enter activation code" autocomplete="off" maxlength="40" required><button class="deposit-continue" type="submit">'+icon('bolt')+' Activate Bot</button></form><p id="bot-passkey-feedback" role="status" class="transfer-caption"></p><p class="transfer-caption">This code unlocks a browser simulation. It is not an account sign-in passkey.</p></section><div id="paper-bot-workspace" hidden><section class="bots-panel bot-settings"><h2>'+icon('settings')+' Bot Settings</h2><p>Stop the bot before changing its settings.</p><form id="paper-settings"><div class="bot-settings-grid"><div class="transfer-field"><label for="bot-asset">Trading Pair</label><select id="bot-asset">'+Object.keys(PAPER_PAIRS).map(p=>'<option>'+p+'</option>').join('')+'</select></div><div class="transfer-field"><label for="bot-amount">Paper Trade Amount ($)</label><input id="bot-amount" inputmode="decimal" value="200.00" required></div><div class="transfer-field"><label for="bot-interval">Trade Interval</label><select id="bot-interval">'+INTERVALS.map(n=>'<option value="'+n+'">'+(n===3600?'1 hour':n/60+' minute'+(n===60?'':'s'))+'</option>').join('')+'</select></div><div class="transfer-field"><label for="bot-leverage">Paper Leverage</label><input id="bot-leverage" type="number" min="1" max="100" value="20" required></div></div><button class="secondary-button" type="submit">Save Settings</button><p id="bot-settings-feedback" role="status" class="transfer-caption"></p></form></section><section class="bots-panel my-bots"><h2>'+icon('bots')+' My Bots (1)</h2><article class="paper-bot-card"><div class="paper-card-heading"><span class="paper-bot-symbol">'+icon('bots')+'</span><div><h3>Pro Trading Bot v2.1</h3><p>Algorithmic trading interface · simulated strategy</p></div><span id="paper-status" class="paper-state">Stopped</span></div><div class="paper-bot-tags"><span id="paper-pair">XAU/USD</span><span>Balanced scenario</span><span>SIMULATED</span></div><div class="paper-progress"><div><span>Next paper trade</span><strong id="paper-countdown">Not running</strong></div><progress id="paper-progress" max="100" value="0"></progress></div><div class="paper-stats"><div><span>Trades</span><strong id="paper-trades">0</strong></div><div><span>Win Rate</span><strong id="paper-win-rate">0.0%</strong></div><div><span>Paper Profit</span><strong id="paper-profit">$0.00</strong></div><div><span>Paper Balance</span><strong id="paper-balance">$10,000.00</strong></div></div><p class="transfer-caption">Generated scenario: 7 wins and 3 losses per completed block of 10 trades. Wins: $50–$60; losses: at most $15 per trade. Short sessions can have a different win rate. These are simulation rules, not a forecast.</p><div class="paper-controls"><button id="paper-start" class="deposit-continue" type="button">'+icon('bolt')+' Start Paper Bot</button><button id="paper-stop" class="transfer-back" type="button" disabled>Stop</button><button id="paper-reset" class="transfer-back" type="button">Reset Paper Account</button></div><p id="paper-feedback" role="status" class="transfer-caption"></p><div id="paper-last-trade"></div><section class="paper-log"><div><h4>Bot Logs <span class="paper-label">SIMULATED</span></h4><small id="paper-log-count">0 entries</small></div><div id="paper-log"></div></section></article></section><section class="bots-panel"><h2>'+icon('trade')+' Paper Trade Log</h2><div id="paper-history"><p class="transfer-caption">No simulated trades yet.</p></div></section></div><p class="transfer-caption">Paper state is saved in this browser for the signed-in account. The bot runs while this page stays open, stops when you leave, and does not backfill trades while closed. No exchange connection is used.</p></div>';}
export function mountBots(root,options={}){mountDashboard(root,{...options,view:'bots',mainHTML:botsHTML()});const page=root.querySelector('.paper-bots'),q=s=>page.querySelector(s);let state=freshPaperBot(),storageKey=options.preview?'aurex-paper-preview-v1':null,ready=!!options.preview,timer=null,startAt=0,due=0,phase=-1;function save(){if(!storageKey)return;try{localStorage.setItem(storageKey,JSON.stringify({...state,running:false}));}catch{q('#paper-feedback').textContent='Browser storage is unavailable. This session will not be saved.';}}
 function log(text){state.logs.push({time:Date.now(),text});state.logs=state.logs.slice(-100);}
 function row(t){return '<article class="paper-trade-row"><div><strong>'+t.side+' '+esc(t.pair)+'</strong><span class="'+(t.win?'positive':'negative')+'">'+(t.profitCents>=0?'+':'')+dollars(t.profitCents)+'</span></div><p>Synthetic entry: '+t.entry.toFixed(t.entry<10?5:2)+' · Exit: '+t.exit.toFixed(t.exit<10?5:2)+' <span class="paper-result '+(t.win?'positive':'negative')+'">'+(t.win?'WIN':'LOSS')+'</span></p><small>'+new Date(t.time).toLocaleString()+' · Paper amount '+dollars(t.amountCents)+' · '+t.leverage+'×</small></article>';}
 function render(){q('#bot-activation').hidden=state.unlocked;q('#paper-bot-workspace').hidden=!state.unlocked;q('#paper-status').textContent=state.running?'Running':'Stopped';q('#paper-status').classList.toggle('running',state.running);q('#paper-pair').textContent=state.settings.pair;q('#paper-trades').textContent=state.trades;q('#paper-win-rate').textContent=(state.trades?state.wins/state.trades*100:0).toFixed(1)+'%';q('#paper-profit').textContent=(state.profitCents>=0?'+':'')+dollars(state.profitCents);q('#paper-profit').className=state.profitCents>=0?'positive':'negative';q('#paper-balance').textContent=dollars(state.balanceCents);q('#paper-start').disabled=state.running||!ready;q('#paper-stop').disabled=!state.running;q('#paper-reset').disabled=state.running;q('#paper-settings').querySelectorAll('input,select,button').forEach(el=>el.disabled=state.running);q('#paper-history').innerHTML=state.history.length?state.history.map(row).join(''):'<p class="transfer-caption">No simulated trades yet.</p>';q('#paper-last-trade').innerHTML=state.history[0]?row(state.history[0]):'';q('#paper-log-count').textContent=state.logs.length+' entries';q('#paper-log').replaceChildren();for(const l of state.logs){const p=document.createElement('p');p.textContent='['+new Date(l.time).toLocaleTimeString()+'] '+l.text;q('#paper-log').append(p);}q('#paper-log').scrollTop=q('#paper-log').scrollHeight;if(!state.running){q('#paper-countdown').textContent='Not running';q('#paper-progress').value=0;}}
 function fill(){q('#bot-asset').value=state.settings.pair;q('#bot-amount').value=(state.settings.amountCents/100).toFixed(2);q('#bot-interval').value=state.settings.interval;q('#bot-leverage').value=state.settings.leverage;}
 function stop(message='Paper bot stopped.'){if(timer)clearInterval(timer);timer=null;state.running=false;if(state.unlocked)log(message);save();if(page.isConnected){render();q('#paper-feedback').textContent=message+' Your real wallet is unchanged.';}}
 function tick(){if(!page.isConnected){stop();return;}const now=Date.now(),elapsed=(now-startAt)/(state.settings.interval*1000),nextPhase=Math.min(4,Math.floor(elapsed*5));if(nextPhase>phase){phase=nextPhase;log(['Simulated market scan…','Simulated trend analysis…','Simulated liquidity check…','Simulated candlestick review…','Generating synthetic trade outcome…'][phase]);render();}q('#paper-countdown').textContent=Math.max(0,Math.ceil((due-now)/1000))+'s / '+state.settings.interval+'s';q('#paper-progress').value=Math.min(100,elapsed*100);if(now>=due){try{const trade=generatePaperTrade(state,now);log('PAPER '+trade.side+' '+trade.pair+' closed: '+(trade.profitCents>=0?'+':'')+dollars(trade.profitCents)+' · '+(trade.win?'WIN':'LOSS'));save();startAt=now;due=now+state.settings.interval*1000;phase=-1;render();}catch(e){stop(e.message);q('#paper-feedback').textContent=e.message;}}}
 q('#bot-passkey-form').onsubmit=e=>{e.preventDefault();const value=q('#bot-passkey').value.trim().toUpperCase();q('#bot-passkey').value='';if(!ready){q('#bot-passkey-feedback').textContent='Sign in before activating your paper bot.';return;}if(value!==ACTIVATION_CODE){q('#bot-passkey-feedback').textContent='Incorrect activation code. Please try again.';return;}state.unlocked=true;log('Pro Trading Bot v2.1 activated for simulated trading.');save();fill();render();};
 q('#paper-settings').onsubmit=e=>{e.preventDefault();try{if(state.running)throw Error('Stop the paper bot before changing settings.');state.settings=validateBotSettings({pair:q('#bot-asset').value,amount:q('#bot-amount').value,interval:q('#bot-interval').value,leverage:q('#bot-leverage').value});save();render();q('#bot-settings-feedback').textContent='Settings saved for your next paper session.';}catch(e){q('#bot-settings-feedback').textContent=e.message;}};
 q('#paper-start').onclick=()=>{try{if(!ready||!state.unlocked)throw Error('Activate the paper bot first.');state.settings=validateBotSettings({pair:q('#bot-asset').value,amount:q('#bot-amount').value,interval:q('#bot-interval').value,leverage:q('#bot-leverage').value});if(state.balanceCents<state.settings.amountCents)throw Error('Insufficient paper funds for this trade amount.');state.running=true;startAt=Date.now();due=startAt+state.settings.interval*1000;phase=-1;log('Paper bot initialized. '+state.settings.pair+' · '+dollars(state.settings.amountCents)+' per trade.');q('#paper-feedback').textContent='Running simulated trades only. Your real wallet is unchanged.';save();render();tick();timer=setInterval(tick,1000);}catch(e){q('#paper-feedback').textContent=e.message;}};
 q('#paper-stop').onclick=()=>stop();q('#paper-reset').onclick=()=>{if(state.running)return;const settings=state.settings;state=freshPaperBot();state.unlocked=true;state.settings=settings;log('Paper account reset to $10,000. Real funds unchanged.');save();render();};
 if(options.preview){try{state=restorePaperBot(localStorage.getItem(storageKey));}catch{}fill();render();}else Promise.resolve(options.getAccounts?.()).then(async accounts=>{const user=await accounts?.user();if(!user)throw Error('Please sign in to activate a paper bot.');if(!page.isConnected)return;storageKey='aurex-paper-v1:'+user.id;try{state=restorePaperBot(localStorage.getItem(storageKey));}catch{}ready=true;fill();render();}).catch(e=>q('#bot-passkey-feedback').textContent=e.message);
 const onPageHide=()=>stop();const observer=new MutationObserver(()=>{if(!page.isConnected){stop('Paper bot stopped when leaving the page.');window.removeEventListener('pagehide',onPageHide);observer.disconnect();}});observer.observe(root,{childList:true,subtree:true});window.addEventListener('pagehide',onPageHide,{once:true});window.scrollTo(0,0);
}
